
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
}

.request-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.mode-banner {
  padding: 8px 12px;
  border-radius: 12px;
  background: rgba(255, 149, 0, 0.1);
  color: #b26a00;
  font-size: 11px;
  line-height: 1.6;
}

.request-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.gen-btn {
  padding: 10px 28px;
  border-radius: 999px;
  background: var(--c-ios-blue);
  color: #fff;
  font-size: 14px;

  &:disabled {
    opacity: 0.5;
  }
}

.request-hint,
.empty,
.error-hint {
  color: var(--c-ios-gray);
  text-align: center;
  font-size: 11px;
  line-height: 1.7;
}

.empty {
  padding: 30px 0;
}

.error-hint {
  color: var(--c-danger);
}

.request-card {
  padding: 12px 14px;
  border-left: 3px solid var(--c-accent);
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);

  &.expanded {
    border-left-color: var(--c-ios-blue);
  }

  &.done,
  &.dropped {
    opacity: 0.66;
  }
}

.request-head {
  width: 100%;
  display: block;
  text-align: left;
}

.request-tags {
  display: flex;
  gap: 5px;
  margin-bottom: 6px;

  span {
    padding: 1px 6px;
    border-radius: 999px;
    background: rgba(10, 132, 255, 0.08);
    color: var(--c-ios-blue);
    font-size: 9px;
  }

  .st-accepted {
    color: var(--c-success);
  }

  .st-done {
    color: var(--c-ios-gray);
  }

  .st-dropped {
    color: var(--c-danger);
  }
}

.request-title {
  margin-bottom: 6px;
  font-size: 14px;
  font-weight: 700;
}

.request-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  color: var(--c-ios-gray);
  font-size: 10px;
}

.request-client {
  color: var(--c-success);
}

.request-body {
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.7;
  white-space: pre-line;
}

.request-detail {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-separator);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.request-hint-line {
  color: var(--c-ios-gray);
  font-size: 12px;
  line-height: 1.6;
}

.request-btns {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  justify-content: center;
}

.mini-btn {
  padding: 6px 16px;
  border-radius: 999px;
  background: rgba(10, 132, 255, 0.1);
  color: var(--c-ios-blue);
  font-size: 12px;

  &.accept {
    background: rgba(40, 199, 111, 0.12);
    color: var(--c-success);
  }

  &.done {
    background: rgba(40, 199, 111, 0.12);
    color: var(--c-success);
  }

  &.drop {
    background: rgba(255, 59, 48, 0.08);
    color: var(--c-danger);
  }
}
