
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
  position: relative;
}

.add-group-btn,
.clear-btn {
  width: 34px;
  height: 34px;
  color: var(--c-ios-blue);
  font-size: 14px;
}

.app-header {
  flex: none;
  min-height: 48px;
  display: flex;
  align-items: center;
  padding: 4px 12px;
  background: rgba(255, 255, 255, 0.78);
  backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--c-separator);
}

.back-btn {
  width: 34px;
  height: 34px;
  color: var(--c-ios-blue);
}

.title-block {
  flex: 1;
  min-width: 0;
  text-align: center;

  h2 {
    font-size: 15px;
    font-weight: 700;
  }

  span {
    display: block;
    overflow: hidden;
    color: var(--c-ios-gray);
    font-size: 9px;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
}

.thread-list {
  flex: 1;
  overflow-y: auto;
}

.thread-item {
  width: 100%;
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  background: #fff;
  text-align: left;

  & + .thread-item {
    border-top: 1px solid var(--c-separator);
  }
}

.avatar {
  width: 46px;
  height: 46px;
  flex: none;
  border-radius: 50%;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #fff;
  font-size: 17px;
  font-weight: 700;
}

.avatar-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.thread-main {
  flex: 1;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.thread-name {
  font-size: 14px;
  font-weight: 700;

  small {
    margin-left: 5px;
    color: var(--c-ios-gray);
    font-size: 9px;
    font-weight: 400;
  }
}

.thread-preview {
  overflow: hidden;
  color: var(--c-ios-gray);
  font-size: 12px;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.thread-arrow {
  color: #c7c7cc;
  font-size: 12px;
}

.unread-badge {
  min-width: 20px;
  height: 20px;
  padding: 0 5px;
  border-radius: 10px;
  background: #ff3b30;
  color: #fff;
  font-size: 11px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.empty-hint {
  padding: 40px 24px;
  text-align: center;
  color: var(--c-ios-gray);
  font-size: 12px;
  line-height: 1.8;
}

.bubble-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 14px 12px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.bubble-row {
  display: flex;
  flex-direction: column;

  &.me {
    align-items: flex-end;
  }

  &.them {
    align-items: flex-start;
  }
}

.sender-label {
  margin: 0 8px 2px;
  color: var(--c-ios-gray);
  font-size: 9px;
}

.bubble {
  max-width: 76%;
  padding: 8px 13px;
  border-radius: 18px;
  font-size: 14px;
  line-height: 1.5;
  word-break: break-word;

  .me & {
    background: var(--c-ios-blue);
    color: #fff;
    border-bottom-right-radius: 4px;
  }

  .them & {
    background: var(--c-bubble-other);
    color: var(--c-text);
    border-bottom-left-radius: 4px;
  }

  &.typing {
    display: flex;
    gap: 4px;
    padding: 12px 14px;

    i {
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #9c9ca1;
      animation: typing-blink 1.2s infinite;
    }
  }
}

@keyframes typing-blink {
  0%,
  60%,
  100% {
    opacity: 0.35;
  }
  30% {
    opacity: 1;
  }
}

.blocked-hint {
  padding: 6px 12px;
  background: rgba(255, 59, 48, 0.08);
  color: var(--c-danger);
  text-align: center;
  font-size: 10px;
}

.input-bar {
  flex: none;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px 10px;
  background: rgba(255, 255, 255, 0.85);
  border-top: 1px solid var(--c-separator);

  input {
    flex: 1;
    height: 36px;
    padding: 0 14px;
    border: 1px solid var(--c-separator);
    border-radius: 18px;
    background: #fff;
    font-size: 14px;
    outline: none;
  }
}

.send-btn {
  width: 34px;
  height: 34px;
  flex: none;
  border-radius: 50%;
  background: var(--c-ios-blue);
  color: #fff;

  &:disabled {
    opacity: 0.4;
  }
}

.creator-mask {
  position: absolute;
  inset: 0;
  z-index: 9;
  display: flex;
  align-items: flex-end;
  background: rgba(0, 0, 0, 0.4);
}

.creator-sheet {
  width: 100%;
  max-height: 78%;
  overflow-y: auto;
  padding: 20px;
  border-radius: 20px 20px 0 0;
  background: var(--c-phone-screen);

  h3 {
    margin-bottom: 12px;
    text-align: center;
    font-size: 17px;
  }
}

.group-title-field {
  display: flex;
  align-items: center;
  gap: 10px;

  span {
    color: var(--c-ios-gray);
    font-size: 12px;
  }

  input {
    flex: 1;
    padding: 8px 10px;
    border: 1px solid var(--c-separator);
    border-radius: 9px;
    background: #fff;
  }
}

.creator-hint {
  margin: 10px 0;
  color: var(--c-ios-gray);
  font-size: 10px;
  line-height: 1.6;
}

.member-list {
  display: flex;
  flex-direction: column;
  gap: 6px;

  label {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 10px;
    border-radius: 9px;
    background: #fff;
    font-size: 12px;
  }
}

.create-btn {
  width: 100%;
  margin-top: 14px;
  padding: 10px;
  border-radius: 10px;
  background: var(--c-ios-blue);
  color: #fff;

  &:disabled {
    opacity: 0.4;
  }
}
