
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
}

.forum-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.forum-actions {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
}

.gen-btn {
  padding: 10px 28px;
  border-radius: 999px;
  background: var(--c-ios-blue);
  color: #fff;
  font-size: 14px;

  &:disabled {
    opacity: 0.5;
  }
}

.forum-hint,
.empty,
.error-hint {
  color: var(--c-ios-gray);
  text-align: center;
  font-size: 11px;
  line-height: 1.7;
}

.empty {
  padding: 30px 0;
}

.error-hint {
  color: var(--c-danger);
}

.post-card {
  padding: 12px 14px;
  border-left: 3px solid var(--c-accent);
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);

  &.expanded {
    border-left-color: var(--c-ios-blue);
  }

  &.folded {
    opacity: 0.72;

    .post-body {
      color: var(--c-ios-gray);
      font-size: 12px;
    }
  }
}

.more-btn {
  align-self: center;
  padding: 8px 22px;
  border-radius: 999px;
  background: rgba(10, 132, 255, 0.1);
  color: var(--c-ios-blue);
  font-size: 12px;

  &:disabled {
    opacity: 0.5;
  }
}

.post-head {
  width: 100%;
  display: block;
  text-align: left;
}

.post-tags {
  display: flex;
  gap: 5px;
  margin-bottom: 6px;

  span {
    padding: 1px 6px;
    border-radius: 999px;
    background: rgba(10, 132, 255, 0.08);
    color: var(--c-ios-blue);
    font-size: 9px;
  }

  .resolved {
    color: var(--c-success);
  }

  .locked {
    color: var(--c-ios-gray);
  }
}

.post-title {
  margin-bottom: 6px;
  font-size: 14px;
  font-weight: 700;
}

.post-meta {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;
  color: var(--c-ios-gray);
  font-size: 10px;
}

.post-author {
  color: var(--c-success);
}

.post-heat {
  margin-left: auto;
  color: #ff9500;
}

.post-body {
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.7;
  white-space: pre-line;
}

.reply-chain {
  margin-top: 10px;
  padding-top: 8px;
  border-top: 1px dashed var(--c-separator);
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.reply-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 3px 8px;
  padding-left: 8px;
  border-left: 2px solid var(--c-separator);
}

.reply-floor {
  color: var(--c-ios-gray);
  font-size: 10px;
}

.reply-author {
  color: var(--c-success);
  font-size: 11px;
}

.reply-body {
  grid-column: 1 / -1;
  color: var(--c-text);
  font-size: 12px;
  line-height: 1.6;
}

.reply-empty {
  color: var(--c-ios-gray);
  text-align: center;
  font-size: 11px;
}

.reply-gen-btn {
  align-self: center;
  padding: 6px 18px;
  border-radius: 999px;
  background: rgba(10, 132, 255, 0.1);
  color: var(--c-ios-blue);
  font-size: 12px;

  &:disabled {
    opacity: 0.5;
  }
}
