
.app-screen {
  flex: 1;
  display: flex;
  flex-direction: column;
  background: var(--c-phone-screen);
  min-height: 0;
}

.sheet-scroll {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.refresh-btn {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: rgba(10, 132, 255, 0.1);
  color: var(--c-ios-blue);
  font-size: 13px;
}

.db-banner {
  padding: 14px 16px;
  border-radius: 12px;
  background: rgba(255, 149, 0, 0.1);
  color: #b26a00;
  font-size: 12px;
  line-height: 1.7;
}

.empty {
  padding: 30px 0;
  color: var(--c-ios-gray);
  text-align: center;
  font-size: 12px;
  line-height: 1.7;
}

.record-card {
  padding: 12px 14px;
  border-radius: 14px;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.05);
  border-left: 3px solid var(--c-accent);

  &.diary {
    border-left-color: #ec5f92;
  }

  &.inventory {
    border-left-color: #f0a53a;
  }
}

.record-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-bottom: 6px;

  span {
    padding: 1px 6px;
    border-radius: 999px;
    background: rgba(10, 132, 255, 0.08);
    color: var(--c-ios-blue);
    font-size: 9px;
  }

  .am-badge {
    background: rgba(240, 165, 58, 0.15);
    color: #b26a00;
  }

  .status-chip {
    background: rgba(40, 199, 111, 0.12);
    color: var(--c-success);
  }

  .writer-chip {
    background: rgba(236, 95, 146, 0.12);
    color: #ec5f92;
  }
}

.record-title {
  margin-bottom: 6px;
  font-size: 14px;
  font-weight: 700;
}

.record-body {
  color: var(--c-text);
  font-size: 13px;
  line-height: 1.7;
  white-space: pre-line;
}

.diary-body {
  color: #8a4a63;
}

.record-quote {
  margin-top: 8px;
  padding: 6px 10px;
  border-left: 2px solid var(--c-separator);
  color: var(--c-ios-gray);
  font-size: 12px;
  line-height: 1.6;
  white-space: pre-line;
}

.record-sub {
  margin-top: 6px;
  color: var(--c-ios-gray);
  font-size: 11px;

  &.thought {
    color: #8a4a63;
  }
}

.inv-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.inv-name {
  font-size: 14px;
  font-weight: 700;
}

.inv-count {
  color: #b26a00;
  font-size: 13px;
  font-weight: 600;
}

.generic-row {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 10px;
  padding: 3px 0;
  font-size: 12px;
}

.generic-key {
  color: var(--c-ios-gray);
  white-space: nowrap;
}

.generic-value {
  color: var(--c-text);
  white-space: pre-line;
}

.more-btn {
  align-self: center;
  padding: 8px 22px;
  border-radius: 999px;
  background: rgba(10, 132, 255, 0.1);
  color: var(--c-ios-blue);
  font-size: 12px;
}
