
.phone-body {
  position: relative;
  width: 392px;
  height: 820px;
  max-height: calc(100vh - 40px);
  padding: 12px;
  border-radius: 54px;
  background: linear-gradient(160deg, var(--c-phone-frame-hi), var(--c-phone-frame) 30%, #17171b);
  box-shadow:
    var(--shadow-phone),
    inset 0 1px 2px rgba(255, 255, 255, 0.25),
    inset 0 -1px 2px rgba(0, 0, 0, 0.5);
}

/* 侧边按键 */
.side-btn {
  position: absolute;
  width: 3px;
  border-radius: 2px;
  background: #3d3d45;

  &--silent {
    left: -2px;
    top: 110px;
    height: 26px;
  }
  &--vol-up {
    left: -2px;
    top: 160px;
    height: 44px;
  }
  &--vol-down {
    left: -2px;
    top: 214px;
    height: 44px;
  }
  &--power {
    right: -2px;
    top: 170px;
    height: 64px;
  }
}

.phone-screen {
  position: relative;
  width: 100%;
  height: 100%;
  border-radius: 42px;
  background: var(--c-phone-screen);
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.status-bar {
  height: 44px;
  flex: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 28px;
  font-size: 13px;
  font-weight: 700;
  color: var(--c-text);
  position: relative;
  z-index: 5;
}

.status-icons {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 12px;
}

.dynamic-island {
  position: absolute;
  top: 10px;
  left: 50%;
  transform: translateX(-50%);
  width: 118px;
  height: 30px;
  border-radius: 20px;
  background: #000;
  z-index: 10;
  pointer-events: none;

  &::after {
    content: '';
    position: absolute;
    right: 16px;
    top: 50%;
    transform: translateY(-50%);
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: #1a1a2e;
    box-shadow: inset 0 0 2px rgba(90, 120, 200, 0.6);
  }
}

.screen-content {
  flex: 1;
  min-height: 0;
  display: flex;
  flex-direction: column;
  position: relative;
}

.home-indicator {
  flex: none;
  height: 22px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: transparent;
  position: relative;
  z-index: 5;

  span {
    width: 134px;
    height: 5px;
    border-radius: 3px;
    background: rgba(0, 0, 0, 0.75);
    transition: opacity 0.2s ease;
  }

  &:hover span {
    opacity: 0.6;
  }
}
